mapper.select:
SELECT * FROM oa_contract_fulfilment_term
WHERE contract_id = #{contractId} AND tenant_id = #{tenantId} AND term_no = #{termNo}
FOR UPDATE

mapper.update:
UPDATE oa_contract_fulfilment_term
SET deleted = #{deleted}, version = version + 1, update_by = #{record.updateBy}, update_time = #{record.updateTime}
WHERE term_id = #{record.termId} AND tenant_id = #{record.tenantId}
  AND version = #{record.version} AND deleted = #{expectedDeleted}
  AND fulfilled_flag = 0 AND waived_flag = 0
